  match r, ph with
  | 1, 0 => farm1_0_0RB1LB_0RC0LB_1RD1RA_1LA1RC
  | _, _ => farm1_0_0RB1LB_0RC0LB_1RD1RA_1LA1RC  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_0RB1LB_0RC0LB_1RD1RA_1LA1RC (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_0RB1LB_0RC0LB_1RD1RA_1LA1RC (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
