Definition mk_0RB1RD_1LC1LA_1RA1LB_0LB0RD (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_0RB1RD_1LC1LA_1RA1LB_0LB0RD.

(** 0RB1RD_1LC1LA_1RA1LB_0LB0RD *)
Definition tm_0RB1RD_1LC1LA_1RA1LB_0LB0RD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB
  | StA, S1 => mk S1 DR StD
  | StB, S0 => mk S1 DL StC
  | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S1 DR StA
  | StC, S1 => mk S1 DL StB
  | StD, S0 => mk S0 DL StB
  | StD, S1 => mk S0 DR StD
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_0RB1RD_1LC1LA_1RA1LB_0LB0RD : list Instr := [(StA, S0)].
Local Notation tm := (tm_wrap_trs tm_0RB1RD_1LC1LA_1RA1LB_0LB0RD pins_0RB1RD_1LC1LA_1RA1LB_0LB0RD).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_0RB1RD_1LC1LA_1RA1LB_0LB0RD : Fam := mkFam 3 [[S0;S0];[S1;S1];[S0;S1]] [] [[]] Binary 1 [mkFill 1 [] 0 [1] 0] StD S0 true [].
Local Notation FAM := fam_0RB1RD_1LC1LA_1RA1LB_0LB0RD.

(** ** The ladder, as DATA

    3 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_0RB1RD_1LC1LA_1RA1LB_0LB0RD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StD (mkS [S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StC (mkS [S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StC (mkS [S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_0RB1RD_1LC1LA_1RA1LB_0LB0RD.

Definition rules_0RB1RD_1LC1LA_1RA1LB_0LB0RD : list LRule := map fst lad.
Local Notation rules := rules_0RB1RD_1LC1LA_1RA1LB_0LB0RD.

Lemma ladder_ok_0RB1RD_1LC1LA_1RA1LB_0LB0RD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_0RB1RD_1LC1LA_1RA1LB_0LB0RD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_0RB1RD_1LC1LA_1RA1LB_0LB0RD. Qed.

