Definition iarm_0RB1RD_1LC1LA_1RA1LB_0LB0RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB1RD_1LC1LA_1RA1LB_0LB0RD
  | 0, 1 => iarm0_1_0RB1RD_1LC1LA_1RA1LB_0LB0RD
  | 1, 0 => iarm1_0_0RB1RD_1LC1LA_1RA1LB_0LB0RD
  | 1, 1 => iarm1_1_0RB1RD_1LC1LA_1RA1LB_0LB0RD
  | _, _ => iarm0_0_0RB1RD_1LC1LA_1RA1LB_0LB0RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_0RB1RD_1LC1LA_1RA1LB_0LB0RD : LRule :=
  mkLRule (mkC StD (mkS [S0;S1] [S0;S1] 1 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S0;S0] [S0;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 [])) 4 8.
Definition ch_farm1_0_0RB1RD_1LC1LA_1RA1LB_0LB0RD : list rstep := [RB (SWin 2);RB (SCycL 2 0);RB (SWinL 4);RB (SCycR 2);RB (SWin 2)].
