(** ** What this board establishes

    32 of 32 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 32 of them
    collapse to 5 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 1 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)
Definition iarm0_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0;S0] [] 0 0 []))
          (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [] 0 0 [])) 0 4.
Definition ch_iarm0_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB : list rstep := [RB (SWin 4)].
Lemma ok_iarm0_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB :
  check_arm tm true false rules iarm0_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB
            ch_iarm0_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm0_1_1RB0RB_0RC0RA_1LD1LC_0LD1RB : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [S1;S1] 1 0 [S0;S0]))
          (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0;S0] [S0;S0] 1 0 [S0;S1])) 4 8.
Definition ch_iarm0_1_1RB0RB_0RC0RA_1LD1LC_0LD1RB : list rstep := [RB (SWin 2);RB (SCycR 2);RB (SWin 4);RB (SCycL 2 0);RB (SWin 2)].
Lemma ok_iarm0_1_1RB0RB_0RC0RA_1LD1LC_0LD1RB :
  check_arm tm true false rules iarm0_1_1RB0RB_0RC0RA_1LD1LC_0LD1RB
            ch_iarm0_1_1RB0RB_0RC0RA_1LD1LC_0LD1RB = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm1_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [] 0 0 []))
          (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 4.
Definition ch_iarm1_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB : list rstep := [RB (SWin 4)].
Lemma ok_iarm1_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB :
  check_arm tm true false rules iarm1_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB
            ch_iarm1_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm1_1_1RB0RB_0RC0RA_1LD1LC_0LD1RB : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [S1;S1] 1 0 [S0;S1]))
          (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0;S0] [S0;S0] 1 0 [S1;S1])) 4 8.
Definition ch_iarm1_1_1RB0RB_0RC0RA_1LD1LC_0LD1RB : list rstep := [RB (SWin 2);RB (SCycR 2);RB (SWin 4);RB (SCycL 2 0);RB (SWin 2)].
Lemma ok_iarm1_1_1RB0RB_0RC0RA_1LD1LC_0LD1RB :
  check_arm tm true false rules iarm1_1_1RB0RB_0RC0RA_1LD1LC_0LD1RB
            ch_iarm1_1_1RB0RB_0RC0RA_1LD1LC_0LD1RB = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB0RB_0RC0RA_1LD1LC_0LD1RB (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB
  | 0, 1 => iarm0_1_1RB0RB_0RC0RA_1LD1LC_0LD1RB
  | 1, 0 => iarm1_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB
  | 1, 1 => iarm1_1_1RB0RB_0RC0RA_1LD1LC_0LD1RB
  | _, _ => iarm0_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [S1;S1] 1 0 []))
          (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0;S0] [S0;S0] 1 0 [S0;S1])) 4 8.
Definition ch_farm1_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB : list rstep := [RB (SWin 2);RB (SCycR 2);RB (SWinR 4);RB (SCycL 2 0);RB (SWin 2)].
Lemma ok_farm1_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB :
  check_arm tm true true rules farm1_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB
            ch_farm1_0_1RB0RB_0RC0RA_1LD1LC_0LD1RB = true.
Proof. vm_compute. reflexivity. Qed.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
