    4, past the last fire of every pinned instruction. *)
Lemma bootq_1RB0RB_0RC0RA_1LD1LC_0LD1RB :
  stepn tm_1RB0RB_0RC0RA_1LD1LC_0LD1RB 4 InitES = Some (lift (fam_cfg FAM ([1], 0, 0))).
