  destruct (csteps tm_1RB0RB_0RC0RA_1LD1LC_0LD1RB 4 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

