  mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [] 0 0 []))
          (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 4.
Definition ch_iarm1_0_1RB0RC_0LB1RC_0RD0RA_1LB1LD : list rstep := [RB (SWin 4)].
