  destruct (csteps tm_1RB0RC_0LB1RC_0RD0RA_1LB1LD 2 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
