  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [] 0 0 []))
          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [] 0 0 [])) 0 4.
Definition ch_iarm1_0_1RB1LC_1LA1RD_0RD0LC_1RB1RA : list rstep := [RB (SWin 4)].
