  match r, ph with
  | 1, 0 => farm1_0_1RB1LC_1LA1RD_1LA1LB_0LC0RD
  | _, _ => farm1_0_1RB1LC_1LA1RD_1LA1LB_0LC0RD  (* unreachable: 0 < r < N0 + st *)
  end.

