Definition iarm_1RB1LC_1LC1RD_1LA1LB_0LC0RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LC_1LC1RD_1LA1LB_0LC0RD
  | 0, 1 => iarm0_1_1RB1LC_1LC1RD_1LA1LB_0LC0RD
  | 1, 0 => iarm1_0_1RB1LC_1LC1RD_1LA1LB_0LC0RD
  | 1, 1 => iarm1_1_1RB1LC_1LC1RD_1LA1LB_0LC0RD
  | _, _ => iarm0_0_1RB1LC_1LC1RD_1LA1LB_0LC0RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

