(** The boot, on the ORIGINAL machine and up to [lift]: the member at index
    11, past the last fire of every pinned instruction. *)
Lemma bootq_1RB1LC_1RC1RD_1LA1LB_0LC0RD :
  stepn tm_1RB1LC_1RC1RD_1LA1LB_0LC0RD 11 InitES = Some (lift (fam_cfg FAM ([0;2], 0, 0))).
Proof.
  assert (H : match csteps tm_1RB1LC_1RC1RD_1LA1LB_0LC0RD 11 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0;2], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm_1RB1LC_1RC1RD_1LA1LB_0LC0RD 11 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

