(** The machine-level theorem, on the QUASIHALTING side: the board above
    runs on the machine wrapped at the pins from the boot member on, and
    [LadderCheckQHTr.boardph_qhtr] closes it. *)
Theorem qhtr_1RB1LC_1RC1RD_1LA1LB_0LC0RD :
  NonHalt tm_1RB1LC_1RC1RD_1LA1LB_0LC0RD /\ QHBoundTr 32779478 tm_1RB1LC_1RC1RD_1LA1LB_0LC0RD /\ QuasiHaltsTr tm_1RB1LC_1RC1RD_1LA1LB_0LC0RD.
Proof.
  apply (boardph_qhtr tm_1RB1LC_1RC1RD_1LA1LB_0LC0RD pins_1RB1LC_1RC1RD_1LA1LB_0LC0RD FAM 1
                      iarm_1RB1LC_1RC1RD_1LA1LB_0LC0RD 1 1
                      farm_1RB1LC_1RC1RD_1LA1LB_0LC0RD 1 1
                      fm1_1RB1LC_1RC1RD_1LA1LB_0LC0RD fm2_1RB1LC_1RC1RD_1LA1LB_0LC0RD 0 vis_1RB1LC_1RC1RD_1LA1LB_0LC0RD
                      [0;2] 0 11 32779478).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
