Definition iarm_1RB1LD_0RC1RC_0LD0RC_1LA1LB (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LD_0RC1RC_0LD0RC_1LA1LB
  | 0, 1 => iarm0_1_1RB1LD_0RC1RC_0LD0RC_1LA1LB
  | 1, 0 => iarm1_0_1RB1LD_0RC1RC_0LD0RC_1LA1LB
  | 1, 1 => iarm1_1_1RB1LD_0RC1RC_0LD0RC_1LA1LB
  | _, _ => iarm0_0_1RB1LD_0RC1RC_0LD0RC_1LA1LB   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1LD_0RC1RC_0LD0RC_1LA1LB : LRule :=
