Definition iarm_1RB1LD_1LB1RC_0LD0RC_1LA1LB (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LD_1LB1RC_0LD0RC_1LA1LB
  | 0, 1 => iarm0_1_1RB1LD_1LB1RC_0LD0RC_1LA1LB
  | 1, 0 => iarm1_0_1RB1LD_1LB1RC_0LD0RC_1LA1LB
