    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LD_1LB1RC_0LD0RC_1LA1LB | exact ok_iarm1_0_1RB1LD_1LB1RC_0LD0RC_1LA1LB]. }
