(* arm135: NO KERNEL CHAIN -- no chain found *)
(** ** What this board establishes

    10 of 16 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 16 of them
    collapse to 5 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 1 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)
Definition iarm0_0_1RB1LD_1RC1RA_1LA1RB_0RB0LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [] 0 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [] 0 0 [])) 0 4.
Definition ch_iarm0_0_1RB1LD_1RC1RA_1LA1RB_0RB0LD : list rstep := [RB (SWin 4)].
Lemma ok_iarm0_0_1RB1LD_1RC1RA_1LA1RB_0RB0LD :
  check_arm tm true false rules iarm0_0_1RB1LD_1RC1RA_1LA1RB_0RB0LD
            ch_iarm0_0_1RB1LD_1RC1RA_1LA1RB_0RB0LD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm0_1_1RB1LD_1RC1RA_1LA1RB_0RB0LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [S0;S1] 1 0 [S0;S0]))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [S0;S0] 1 0 [S1;S1])) 4 8.
Definition ch_iarm0_1_1RB1LD_1RC1RA_1LA1RB_0RB0LD : list rstep := [RB (SWin 2);RB (SCycR 2);RB (SWin 4);RB (SCycL 2 0);RB (SWin 2)].
Lemma ok_iarm0_1_1RB1LD_1RC1RA_1LA1RB_0RB0LD :
  check_arm tm true false rules iarm0_1_1RB1LD_1RC1RA_1LA1RB_0RB0LD
            ch_iarm0_1_1RB1LD_1RC1RA_1LA1RB_0RB0LD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm1_0_1RB1LD_1RC1RA_1LA1RB_0RB0LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [] 0 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [] 0 0 [])) 0 4.
Definition ch_iarm1_0_1RB1LD_1RC1RA_1LA1RB_0RB0LD : list rstep := [RB (SWin 4)].
Lemma ok_iarm1_0_1RB1LD_1RC1RA_1LA1RB_0RB0LD :
  check_arm tm true false rules iarm1_0_1RB1LD_1RC1RA_1LA1RB_0RB0LD
            ch_iarm1_0_1RB1LD_1RC1RA_1LA1RB_0RB0LD = true.
Proof. vm_compute. reflexivity. Qed.

