Lemma farm_rhs_1RB1LD_1RC1RA_1LA1RB_0RB0LD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_rhs (farm_1RB1LD_1RC1RA_1LA1RB_0RB0LD r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_1RB1LD_1RC1RA_1LA1RB_0RB0LD r ph)
