Definition mk_1RB1RB_0LC0RB_1LD1LA_1RA1LC (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_1RB1RB_0LC0RB_1LD1LA_1RA1LC.

(** 1RB1RB_0LC0RB_1LD1LA_1RA1LC *)
Definition tm_1RB1RB_0LC0RB_1LD1LA_1RA1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S1 DR StB
  | StB, S0 => mk S0 DL StC
  | StB, S1 => mk S0 DR StB
  | StC, S0 => mk S1 DL StD
  | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S1 DR StA
  | StD, S1 => mk S1 DL StC
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB1RB_0LC0RB_1LD1LA_1RA1LC : list Instr := [(StA, S0)].
Local Notation tm := (tm_wrap_trs tm_1RB1RB_0LC0RB_1LD1LA_1RA1LC pins_1RB1RB_0LC0RB_1LD1LA_1RA1LC).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB1RB_0LC0RB_1LD1LA_1RA1LC : Fam := mkFam 3 [[S0;S0];[S1;S1];[S0;S1]] [] [[]] Binary 1 [mkFill 1 [] 0 [1] 0] StB S0 true [].
Local Notation FAM := fam_1RB1RB_0LC0RB_1LD1LA_1RA1LC.

(** ** The ladder, as DATA

    3 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1RB_0LC0RB_1LD1LA_1RA1LC : list (LRule * list rstep) :=
  [(mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StB (mkS [S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StD (mkS [S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StD (mkS [S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_1RB1RB_0LC0RB_1LD1LA_1RA1LC.

Definition rules_1RB1RB_0LC0RB_1LD1LA_1RA1LC : list LRule := map fst lad.
Local Notation rules := rules_1RB1RB_0LC0RB_1LD1LA_1RA1LC.

Lemma ladder_ok_1RB1RB_0LC0RB_1LD1LA_1RA1LC : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1RB_0LC0RB_1LD1LA_1RA1LC : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1RB_0LC0RB_1LD1LA_1RA1LC. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(* B[0] L<> R<>  ==>  B[0] L<1^2> R<>   [4 steps] *)
Definition arm70_1RB1RB_0LC0RB_1LD1LA_1RA1LC : LRule :=
  mkLRule (mkC StB (mkS [] [] 0 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StB (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 4.
Definition ch_arm70_1RB1RB_0LC0RB_1LD1LA_1RA1LC : list rstep := [RB (SWinL 4)].
Lemma ok_arm70_1RB1RB_0LC0RB_1LD1LA_1RA1LC :
  check_arm tm true true rules arm70_1RB1RB_0LC0RB_1LD1LA_1RA1LC ch_arm70_1RB1RB_0LC0RB_1LD1LA_1RA1LC = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm70_1RB1RB_0LC0RB_1LD1LA_1RA1LC : RuleSound tm true true arm70_1RB1RB_0LC0RB_1LD1LA_1RA1LC.
Proof. eapply arm_sound; [exact rules_sound_1RB1RB_0LC0RB_1LD1LA_1RA1LC | exact ok_arm70_1RB1RB_0LC0RB_1LD1LA_1RA1LC]. Qed.

