Definition iarm_1RB1RD_1LC1LA_1RA1LB_0LB0RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1RD_1LC1LA_1RA1LB_0LB0RD
  | 0, 1 => iarm0_1_1RB1RD_1LC1LA_1RA1LB_0LB0RD
  | 1, 0 => iarm1_0_1RB1RD_1LC1LA_1RA1LB_0LB0RD
  | 1, 1 => iarm1_1_1RB1RD_1LC1LA_1RA1LB_0LB0RD
  | _, _ => iarm0_0_1RB1RD_1LC1LA_1RA1LB_0LB0RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

