          (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0;S0] [S0;S0] 1 0 [S0;S1])) 4 8.
Definition ch_iarm0_1_1RB____0RC0RB_1LD1LC_0LD1RB : list rstep := [RB (SWin 2);RB (SCycR 2);RB (SWin 4);RB (SCycL 2 0);RB (SWin 2)].
