Definition iarm_1RB____0RC0RB_1LD1LC_0LD1RB (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB____0RC0RB_1LD1LC_0LD1RB
  | 0, 1 => iarm0_1_1RB____0RC0RB_1LD1LC_0LD1RB
  | 1, 0 => iarm1_0_1RB____0RC0RB_1LD1LC_0LD1RB
  | 1, 1 => iarm1_1_1RB____0RC0RB_1LD1LC_0LD1RB
  | _, _ => iarm0_0_1RB____0RC0RB_1LD1LC_0LD1RB   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB____0RC0RB_1LD1LC_0LD1RB : LRule :=
