(** The boot, on the ORIGINAL machine and up to [lift]: the member at index
    8, past the last fire of every pinned instruction. *)
Lemma bootq_1RB____1LC1LB_0LC1RD_0RB0RD :
  stepn tm_1RB____1LC1LB_0LC1RD_0RB0RD 8 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm_1RB____1LC1LB_0LC1RD_0RB0RD 8 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm_1RB____1LC1LB_0LC1RD_0RB0RD 8 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

